import { BrowserWindow } from 'electrobun/main'
import { applyWindowIcon } from './windowIcon'

// Generated by scripts/prepare-electrobun-api.mjs before every desktop build.
const { startApiServer } = require('../../server/desktop-api.bundle.cjs') as {
  startApiServer: () => Promise<void>
}

try {
  await startApiServer()
  console.log('[desktop] bundled API server ready on http://127.0.0.1:13000')
} catch (error) {
  console.error('[desktop] failed to start bundled API server:', error)
}

new BrowserWindow({
  title: '声屿',
  url: 'views://mainview/index.html',
  frame: {
    width: 1440,
    height: 900,
    x: 80,
    y: 60,
  },
})

applyWindowIcon()

console.log('[desktop] Electrobun app started')
